import type { LessonCompletionLogic } from "@shecancode/shared-types";

export function isBlockStructureCompletionLogic(logic: LessonCompletionLogic): boolean {
  switch (logic.type) {
    case "required_block_types":
    case "ordered_block_types":
    case "max_top_level_blocks":
    case "variable_name":
      return true;
    case "print_text":
    case "print_sequence":
    case "repeat_print":
    case "if_print":
    case "variable_value":
    case "variable_then_print":
      return false;
    default: {
      const _exhaustive: never = logic;
      return _exhaustive;
    }
  }
}

import type { BlockKind, LessonCompletionLogic, ProgramWorkspace, WorkspaceBlock } from "@shecancode/shared-types";

function someBlock(blocks: WorkspaceBlock[], predicate: (block: WorkspaceBlock) => boolean): boolean {
  return blocks.some((block) => predicate(block) || someBlock(block.children ?? [], predicate));
}

function includesOrderedTypes(blocks: WorkspaceBlock[], blockTypes: BlockKind[]): boolean {
  let nextIndex = 0;
  for (const block of blocks) {
    if (block.type === blockTypes[nextIndex]) nextIndex += 1;
  }
  return nextIndex === blockTypes.length;
}

export function evaluateBlockStructureLogic(logic: LessonCompletionLogic, workspace: ProgramWorkspace): boolean {
  switch (logic.type) {
    case "required_block_types":
      return logic.blockTypes.every((blockType) => someBlock(workspace.blocks, (block) => block.type === blockType));

    case "ordered_block_types":
      return includesOrderedTypes(workspace.blocks, logic.blockTypes);

    case "max_top_level_blocks": {
      const allowedTypes = new Set<BlockKind>(logic.blockTypes);
      const count = workspace.blocks.filter((block) => allowedTypes.has(block.type)).length;
      return count <= logic.max;
    }

    case "variable_name": {
      const expectedName = logic.name.trim();
      return someBlock(
        workspace.blocks,
        (block) => block.type === "variable" && typeof block.fields?.name === "string" && block.fields.name.trim() === expectedName,
      );
    }

    case "print_text":
    case "print_sequence":
    case "repeat_print":
    case "if_print":
    case "variable_value":
    case "variable_then_print":
      throw new Error(`evaluateBlockStructureLogic does not handle runtime logic variant: ${logic.type}`);

    default: {
      const _exhaustive: never = logic;
      return _exhaustive;
    }
  }
}

import type {
  LessonCompletionLogic,
  ProgramExecutionResult,
  ProgramWorkspace,
  WorkspaceBlock,
} from "@shecancode/shared-types";

function flattenBlocks(blocks: WorkspaceBlock[]): WorkspaceBlock[] {
  return blocks.flatMap((block) => [block, ...flattenBlocks(block.children ?? [])]);
}

function normalizeText(value: string) {
  return value
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/\s+/g, " ");
}

function comparableValue(value: string | number | boolean) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    const num = Number(trimmed);
    if (trimmed !== "" && Number.isFinite(num)) return num;
    return normalizeText(trimmed);
  }
  return value;
}

function validatePrintText(output: string[], text: string) {
  return output.length === 1 && normalizeText(output[0] ?? "") === normalizeText(text);
}

function findVariableBlock(blocks: WorkspaceBlock[], expectedName: string) {
  const normalizedName = normalizeText(expectedName);
  return blocks.find(
    (block) =>
      block.type === "variable" &&
      typeof block.fields?.name === "string" &&
      normalizeText(block.fields.name) === normalizedName,
  );
}

export function evaluateRuntimeLogic(
  logic: LessonCompletionLogic,
  workspace: ProgramWorkspace,
  executionResult: ProgramExecutionResult,
): boolean {
  const allBlocks = flattenBlocks(workspace.blocks);

  switch (logic.type) {
    case "print_text":
      return validatePrintText(executionResult.output, logic.text);
    case "print_sequence":
      return (
        executionResult.output.length === logic.texts.length &&
        logic.texts.every((text, index) => normalizeText(executionResult.output[index] ?? "") === normalizeText(text))
      );
    case "repeat_print": {
      const expected = Array(logic.count).fill(logic.text);
      return (
        executionResult.output.length === expected.length &&
        expected.every((text, index) => normalizeText(executionResult.output[index] ?? "") === normalizeText(text))
      );
    }
    case "if_print": {
      const ifBlock = allBlocks.find((block) => block.type === "if");
      const childPrint = ifBlock?.children?.find((child) => child.type === "print");
      const matchesChild =
        typeof childPrint?.fields?.text === "string" &&
        normalizeText(childPrint.fields.text) === normalizeText(logic.text);
      return validatePrintText(executionResult.output, logic.text) && matchesChild;
    }
    case "variable_value": {
      const variableBlock = findVariableBlock(allBlocks, logic.name);
      return comparableValue(variableBlock?.fields?.value as string | number | boolean) === comparableValue(logic.value);
    }
    case "variable_then_print": {
      const variableBlock = findVariableBlock(allBlocks, logic.name);
      const variableMatches =
        comparableValue(variableBlock?.fields?.value as string | number | boolean) === comparableValue(logic.value);
      return variableMatches && validatePrintText(executionResult.output, String(logic.value));
    }
    case "required_block_types":
    case "ordered_block_types":
    case "max_top_level_blocks":
    case "variable_name":
      throw new Error(`evaluateRuntimeLogic does not handle block-structure variant: ${logic.type}`);
    default: {
      const _exhaustive: never = logic;
      return _exhaustive;
    }
  }
}

function orderedTopLevelTypes(blocks: WorkspaceBlock[], requiredTypes: BlockKind[]) {
  return requiredTypes.every((type, index) => blocks[index]?.type === type);
}

function findVariableBlock(blocks: WorkspaceBlock[], expectedName: string) {
  const normalizedName = normalizeText(expectedName);
  return blocks.find(
    (block) =>
      block.type === "variable" &&
      typeof block.fields?.name === "string" &&
      normalizeText(block.fields.name) === normalizedName,
  );
}

function validatePrintText(output: string[], text: string) {
  return output.length === 1 && normalizeText(output[0] ?? "") === normalizeText(text);
}

function evaluateCompletionLogic(
  completionLogic: LessonCompletionLogic,
  program: ProgramWorkspace,
  executionResult: ProgramExecutionResult,
): LessonStepEvaluationResult {
  const allBlocks = flattenBlocks(program.blocks);

  switch (completionLogic.type) {
    case "required_block_types":
      return hasBlockTypes(allBlocks, completionLogic.blockTypes)
        ? { completed: true, feedback: "Bạn đã thêm đúng các khối cần thiết cho bước này." }
        : { completed: false, feedback: "Bước này vẫn thiếu một số khối quan trọng. Hãy nhìn lại gợi ý bên phải." };

    case "ordered_block_types":
      return orderedTopLevelTypes(program.blocks, completionLogic.blockTypes)
        ? { completed: true, feedback: "Thứ tự khối đã đúng. Bạn có thể tiếp tục." }
        : { completed: false, feedback: "Các khối chính chưa nằm đúng thứ tự từ trên xuống dưới." };

    case "print_text":
      return validatePrintText(executionResult.output, completionLogic.text)
        ? { completed: true, feedback: "Đầu ra đã khớp với mục tiêu của bài." }
        : { completed: false, feedback: "Đầu ra chưa khớp với thông điệp cần in." };

    case "print_sequence": {
      const matches =
        executionResult.output.length === completionLogic.texts.length &&
        completionLogic.texts.every(
          (text, index) => normalizeText(executionResult.output[index] ?? "") === normalizeText(text),
        );

      return matches
        ? { completed: true, feedback: "Bạn đã in đúng chuỗi thông điệp theo thứ tự." }
        : { completed: false, feedback: "Các thông điệp in ra chưa đúng nội dung hoặc thứ tự." };
    }

    case "repeat_print": {
      const expectedOutput = Array.from({ length: completionLogic.count }, () => completionLogic.text);
      const matches =
        executionResult.output.length === expectedOutput.length &&
        expectedOutput.every(
          (text, index) => normalizeText(executionResult.output[index] ?? "") === normalizeText(text),
        );

      return matches
        ? { completed: true, feedback: "Vòng lặp đang hoạt động đúng như mong đợi." }
        : { completed: false, feedback: "Vòng lặp chưa cho ra đúng số lần hoặc đúng thông điệp." };
    }

    case "max_top_level_blocks":
      return orderedTopLevelTypes(program.blocks, completionLogic.blockTypes) && program.blocks.length <= completionLogic.max
        ? { completed: true, feedback: "Lời giải gọn và đúng. Bạn đang dùng vòng lặp hiệu quả." }
        : { completed: false, feedback: "Bài này cần lời giải ngắn gọn hơn với số khối cấp cao ít hơn." };

    case "if_print": {
      const ifBlock = allBlocks.find((block) => block.type === "if");
      const childPrint = ifBlock?.children?.find((child) => child.type === "print");
      const matchesOutput = validatePrintText(executionResult.output, completionLogic.text);
      const matchesChild =
        typeof childPrint?.fields?.text === "string" &&
        normalizeText(childPrint.fields.text) === normalizeText(completionLogic.text);

      return matchesOutput && matchesChild
        ? { completed: true, feedback: "Khối điều kiện đã chứa đúng hành động cần thực hiện." }
        : { completed: false, feedback: "Khối điều kiện hoặc nội dung bên trong chưa đúng với yêu cầu." };
    }

    case "variable_name":
      return findVariableBlock(allBlocks, completionLogic.name)
        ? { completed: true, feedback: "Bạn đã tạo đúng biến cần dùng trong bài." }
        : { completed: false, feedback: "Khối biến chưa có đúng tên được yêu cầu." };

    case "variable_value": {
      const variableBlock = findVariableBlock(allBlocks, completionLogic.name);
      const currentValue = variableBlock?.fields?.value;

      return comparableValue(currentValue as string | number | boolean) === comparableValue(completionLogic.value)
        ? { completed: true, feedback: "Biến đã được gán đúng giá trị." }
        : { completed: false, feedback: "Giá trị của biến vẫn chưa khớp với yêu cầu." };
    }

    case "variable_then_print": {
      const variableBlock = findVariableBlock(allBlocks, completionLogic.name);
      const variableMatches =
        comparableValue(variableBlock?.fields?.value as string | number | boolean) === comparableValue(completionLogic.value);
      const outputMatches = validatePrintText(executionResult.output, String(completionLogic.value));

      return variableMatches && outputMatches
        ? { completed: true, feedback: "Bạn đã lưu và dùng lại giá trị của biến đúng cách." }
        : { completed: false, feedback: "Chương trình vẫn chưa dùng biến đúng như yêu cầu của bài." };
    }
  }
}

